// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address private ownerAddress;

    function setUp() public {
        ownerAddress = address(this);
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function testFuzz_property(address caller, address tokenOwner, uint256 tokens) public {
        vm.assume(caller != ownerAddress);

        RecordingToken token = new RecordingToken();

        vm.prank(caller);
        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSelector(
                PoCGame.transferAnyERC20Token.selector,
                address(token),
                tokenOwner,
                tokens
            )
        );

        bool returnedTrue = ok && data.length >= 32 && abi.decode(data, (bool));

        assertTrue(!(returnedTrue && token.callCount() > 0),
            "non-owner call to transferAnyERC20Token must not reach the token's transfer");
    }
}

contract RecordingToken {
    uint256 public callCount;

    function transfer(address, uint256) external returns (bool) {
        callCount += 1;
        return true;
    }
}
